CREATE VIEW public.active_members AS
 SELECT m.id,
    m.id_unidade AS unit_id,
    m.nome,
    m.cpf,
    m.rg,
    m.email,
    m.telefone,
    m.whatsapp AS celular,
    m.data_nascimento,
    m.sexo,
    m.estado_civil,
    m.logradouro,
    m.bairro,
    m.cidade,
    m.estado,
    m.cep,
    m.data_conversao,
    m.data_batismo,
    m.data_membro,
    m.status AS status_membro,
    m.funcao AS cargo_igreja,
    m.ministerio,
    m.grupo_pequeno,
