    m.criado AS created_at,
    m.atualizado AS updated_at,
    u.nome_unidade AS unit_name
   FROM (public.membros m
     JOIN public.units u ON ((m.id_unidade = u.id)))
  WHERE (m.status = 'ATIVO'::text);


